#include "PluginEditor.h"
VoltaAudioProcessorEditor::VoltaAudioProcessorEditor(VoltaAudioProcessor&x):AudioProcessorEditor(&x),p(x){knobs={&mix,&det,&cut,&res,&a,&d,&s,&r,&tube,&iron,&voltage};const char*ids[]={"mix","detune","cutoff","res","attack","decay","sustain","release","tube","iron","voltage"};for(int i=0;i<11;++i){auto*k=knobs[i];k->setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);k->setTextBoxStyle(juce::Slider::TextBoxBelow,false,72,18);addAndMakeVisible(*k);at.push_back(std::make_unique<SA>(p.apvts,ids[i],*k));}setSize(920,520);}
void VoltaAudioProcessorEditor::paint(juce::Graphics&g){g.fillAll(juce::Colour(0xff151515));g.setColour(juce::Colour(0xffffd34e));g.setFont(44);g.drawText("V O L T A",25,18,getWidth()-50,55,juce::Justification::centred);g.setFont(14);g.drawText("OSC MIX     DETUNE      CUTOFF      RESONANCE      ATTACK      DECAY      SUSTAIN      RELEASE      TUBE DRIVE      IRON      VOLTAGE",20,405,getWidth()-40,30,juce::Justification::centred);g.setColour(juce::Colours::white);g.setFont(13);g.drawText("POLYPHONIC HIGH-VOLTAGE ANALOG SYNTHESIZER",20,70,getWidth()-40,24,juce::Justification::centred);}
void VoltaAudioProcessorEditor::resized(){int x=18,y=135,w=76,gap=6;for(auto*k:knobs){k->setBounds(x,y,w,245);x+=w+gap;}}
